"use client";

import React, { useEffect, useId, useRef, useState } from 'react';

// The original supplied SVG is embedded below. No companion asset is required.
const SWITCH_FRAME = 'data:image/svg+xml;base64,';

// Self-contained sample images. Replace `image` with any URL or imported asset.
function landscape(sky, glow, ridge, foreground, variant) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="1000" viewBox="0 0 1400 1000"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="${glow}"/></linearGradient><radialGradient id="halo"><stop stop-color="${glow}" stop-opacity=".65"/><stop offset="1" stop-color="${glow}" stop-opacity="0"/></radialGradient><linearGradient id="land" x2=".8" y2="1"><stop stop-color="${ridge}"/><stop offset="1" stop-color="${foreground}"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h1400v1000H0z"/><ellipse cx="990" cy="290" rx="430" ry="390" fill="url(#halo)"/><circle cx="${variant % 2 ? 980 : 900}" cy="260" r="115" fill="${glow}" opacity=".9"/><g fill="#fff" opacity=".55"><circle cx="160" cy="150" r="2"/><circle cx="440" cy="260" r="2"/><circle cx="680" cy="100" r="2"/><circle cx="1150" cy="120" r="2"/><circle cx="1230" cy="400" r="2"/></g><path d="M0 610 180 460 360 540 670 240 880 530 1120 370 1400 570V1000H0Z" fill="${ridge}"/><path d="m360 540 310-300 210 290-188-130-56 61-30-55Z" fill="${glow}" opacity=".28"/><path d="M0 700 270 540 570 800 990 480 1400 740V1000H0Z" fill="url(#land)"/><path d="M0 830Q250 700 490 880T990 790T1400 840V1000H0Z" fill="${foreground}"/><path d="M700 1000 980 670 910 795 1070 740 900 900 1000 870 920 1000" fill="${glow}" opacity=".18"/></svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

export const demoCards = [
  { id: 'explora', eyebrow: '01 / EXPLORA', title: 'Un mundo por descubrir.', subtitle: 'Las mejores historias empiezan con un poco de curiosidad.', image: landscape('#17102f', '#f4b8e8', '#7661a2', '#25213f', 0) },
  { id: 'respira', eyebrow: '02 / RESPIRA', title: 'Encuentra tu propio ritmo.', subtitle: 'Haz una pausa. A veces, la aventura está en el camino.', image: landscape('#073e42', '#d6f5b7', '#438c7a', '#102f35', 1) },
  { id: 'imagina', eyebrow: '03 / IMAGINA', title: 'Cambia de perspectiva.', subtitle: 'Hay lugares que solo existen cuando te atreves a imaginarlos.', image: landscape('#343176', '#ffbaa7', '#b87798', '#302645', 2) },
  { id: 'atrevete', eyebrow: '04 / ATRÉVETE', title: 'Ve un poco más lejos.', subtitle: 'Un nuevo horizonte. Una nueva manera de ver las cosas.', image: landscape('#632d32', '#ffda9e', '#c17756', '#442b34', 3) },
  { id: 'conecta', eyebrow: '05 / CONECTA', title: 'Comparte el viaje.', subtitle: 'Los grandes momentos se disfrutan más en buena compañía.', image: landscape('#102b59', '#a1e5f0', '#3f7998', '#142d48', 4) },
  { id: 'empieza', eyebrow: '06 / EMPIEZA', title: 'Tu próxima historia.', subtitle: 'Todo empieza aquí. El siguiente paso lo eliges tú.', image: landscape('#363b26', '#f2f5b1', '#9a995d', '#30392c', 5) },
];

/**
 * Portable React component: frame, sample imagery, styles and behavior in one file.
 * cards: { id?, eyebrow?, title, subtitle?, image?, imagePosition?, href?, linkLabel? }[]
 * maxWidth: desktop console width in pixels. scrollStep: viewport heights per card.
 * Needs a normally scrolling document; avoid overflow/transform on sticky ancestors.
 */
export default function SwitchScroll({ cards = demoCards, maxWidth = 1140, scrollStep = 0.7, className = '', style, onCardChange }) {
  const root = useRef(null);
  const track = useRef(null);
  const callback = useRef(onCardChange);
  const [active, setActive] = useState(0);
  const id = useId();
  const count = cards.length;
  const step = Math.max(0.25, Number(scrollStep) || 0.7);
  const selected = Math.min(active, Math.max(0, count - 1));
  callback.current = onCardChange;

  useEffect(() => {
    const section = root.current;
    if (!section || !count) return;
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
    let frame = 0;
    let previous = -1;
    const update = () => {
      frame = 0;
      const sticky = section.querySelector('.ss-sticky');
      const travel = section.offsetHeight - sticky.offsetHeight;
      const progress = travel > 0 ? Math.max(0, Math.min(count - 1, (-section.getBoundingClientRect().top / travel) * (count - 1))) : 0;
      const next = Math.round(progress);
      // Fade out completely before changing cards; never show two at once.
      const distance = Math.abs(progress - next);
      const fade = Math.max(0, Math.min(1, (0.5 - distance) / 0.3));
      const opacity = reduce.matches ? 1 : fade * fade * (3 - 2 * fade);
      track.current?.style.setProperty('--card-opacity', String(opacity));
      if (next !== previous) {
        previous = next;
        setActive(next);
        callback.current?.(next);
      }
    };
    const schedule = () => { if (!frame) frame = requestAnimationFrame(update); };
    const observer = new ResizeObserver(schedule);
    observer.observe(section);
    observer.observe(section.querySelector('.ss-sticky'));
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', schedule);
    reduce.addEventListener('change', schedule);
    update();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      window.removeEventListener('scroll', schedule);
      window.removeEventListener('resize', schedule);
      reduce.removeEventListener('change', schedule);
    };
  }, [count, step]);

  function goTo(index) {
    const section = root.current;
    if (!section) return;
    const next = Math.max(0, Math.min(count - 1, index));
    const travel = section.offsetHeight - section.querySelector('.ss-sticky').offsetHeight;
    const start = window.scrollY + section.getBoundingClientRect().top;
    window.scrollTo({ top: start + (count > 1 ? (next / (count - 1)) * travel : 0), behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
  }

  function onKeyDown(event) {
    // Keep native button/link activation and Tab navigation intact.
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destinations = { ArrowDown: selected + 1, ArrowRight: selected + 1, ArrowUp: selected - 1, ArrowLeft: selected - 1, Home: 0, End: count - 1 };
    if (event.key in destinations) {
      event.preventDefault();
      goTo(destinations[event.key]);
    }
  }

  if (!count) return null;

  return (
    <section ref={root} className={`switch-scroll ${className}`} aria-label="Historias en Nintendo Switch" aria-roledescription="carrusel" onKeyDown={onKeyDown} style={{ '--switch-width': `${maxWidth}px`, '--switch-travel': `${(count - 1) * step * 100}svh`, ...style }}>
      <style>{`
        .switch-scroll { position:relative; height:calc(100svh + var(--switch-travel)); width:100%; font-family:Arial, Helvetica, sans-serif; color:#fff; }
        .switch-scroll, .switch-scroll * { box-sizing:border-box; }
        .switch-scroll .ss-sticky { position:sticky; top:0; height:100svh; display:flex; align-items:center; justify-content:center; padding:24px; }
        .switch-scroll .ss-device { position:relative; width:min(100%, var(--switch-width), calc(82svh * 2061 / 763)); aspect-ratio:2061 / 763; container-type:inline-size; isolation:isolate; }
        .switch-scroll .ss-frame { position:absolute; z-index:2; inset:0; width:100%; height:100%; pointer-events:none; user-select:none; }
        .switch-scroll .ss-screen { position:absolute; z-index:1; left:18.53%; top:8.65%; width:63.15%; height:79.2%; border-radius:1.1% / 2.5%; overflow:hidden; background:#17102f; }
        .switch-scroll .ss-track { position:relative; width:100%; height:100%; }
        .switch-scroll .ss-card { position:absolute; inset:0; width:100%; height:100%; overflow:hidden; background:#25213f; opacity:0; visibility:hidden; }
        .switch-scroll .ss-card[aria-hidden="false"] { opacity:var(--card-opacity,1); visibility:visible; }
        .switch-scroll .ss-art { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
        .switch-scroll .ss-shade { position:absolute; inset:0; background:linear-gradient(90deg,rgba(8,9,24,.5),transparent 95%),linear-gradient(0deg,rgba(8,9,24,.82),transparent 85%); }
        .switch-scroll .ss-copy { position:absolute; left:7%; right:9%; bottom:19%; }
        .switch-scroll .ss-eyebrow { display:block; margin:0 0 14px; color:#ecffae; font-size:clamp(10px,1.1cqw,13px); line-height:1.4; letter-spacing:.15em; font-weight:600; }
        .switch-scroll .ss-title { max-width:13em; margin:0; font-size:clamp(24px,4.4cqw,52px); line-height:1.02; letter-spacing:-.045em; font-weight:600; text-wrap:balance; }
        .switch-scroll .ss-subtitle { max-width:30em; margin:14px 0 0; font-size:clamp(12px,1.4cqw,16px); line-height:1.55; color:rgba(255,255,255,.84); text-wrap:pretty; }
        .switch-scroll .ss-link { display:inline-block; color:white; font-size:14px; margin-top:16px; text-underline-offset:4px; }
        .switch-scroll a:focus-visible { outline:2px solid #e1ff71; outline-offset:3px; }
        .switch-scroll .ss-sr { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
        @media (max-width:1024px) and (orientation:portrait), (max-width:700px) {
          .switch-scroll .ss-sticky { padding:20px 12px; }
          .switch-scroll .ss-device { width:min(100%, 360px, calc(88svh * 763 / 2061)); aspect-ratio:763 / 2061; }
          .switch-scroll .ss-frame { inset:auto; top:50%; left:50%; width:270.117955%; height:37.020864%; max-width:none; transform:translate(-50%,-50%) rotate(90deg); }
          .switch-scroll .ss-screen { left:12.15%; top:18.53%; width:79.2%; height:63.15%; border-radius:2.5% / 1.1%; }
          .switch-scroll .ss-art { object-position:64% center; }
          .switch-scroll .ss-copy { left:9%; right:9%; bottom:27%; }
          .switch-scroll .ss-eyebrow { font-size:11px; letter-spacing:.1em; margin-bottom:16px; }
          .switch-scroll .ss-title { font-size:clamp(26px,11cqw,40px); line-height:1.06; }
          .switch-scroll .ss-subtitle { font-size:14px; line-height:1.55; margin-top:16px; }
        }
        @media (max-height:500px) and (orientation:landscape) {
          .switch-scroll .ss-device { width:min(100%, var(--switch-width), calc(94svh * 2061 / 763)); }
          .switch-scroll .ss-sticky { padding:8px 20px; }
          .switch-scroll .ss-eyebrow { margin-bottom:6px; font-size:10px; }
          .switch-scroll .ss-title { font-size:clamp(20px,3.6cqw,36px); }
          .switch-scroll .ss-subtitle { margin-top:8px; }
          .switch-scroll .ss-copy { bottom:23%; }
        }
      `}</style>
      <div className="ss-sticky">
        <div className="ss-device">
          <div className="ss-screen" id={`${id}-screen`}>
            <div className="ss-track" ref={track}>
              {cards.map((card, index) => (
                <article className="ss-card" key={card.id ?? index} aria-label={`${index + 1} de ${count}: ${card.title}`} aria-hidden={selected !== index} inert={selected !== index}>
                  {card.image && <img className="ss-art" src={card.image} style={card.imagePosition ? { objectPosition: card.imagePosition } : undefined} alt="" draggable="false" decoding="async" />}
                  <div className="ss-shade" />
                  <div className="ss-copy">
                    {card.eyebrow && <span className="ss-eyebrow">{card.eyebrow}</span>}
                    <h2 className="ss-title">{card.title}</h2>
                    {card.subtitle && <p className="ss-subtitle">{card.subtitle}</p>}
                    {card.href && <a className="ss-link" href={card.href}>{card.linkLabel || 'Descubrir'} ↗</a>}
                  </div>
                </article>
              ))}
            </div>
          </div>
          <img className="ss-frame" src={SWITCH_FRAME} alt="" draggable="false" />
          <p className="ss-sr" aria-live="polite" aria-atomic="true">Tarjeta {selected + 1} de {count}: {cards[selected]?.title}</p>
        </div>
      </div>
    </section>
  );
}
